    float xi1,
    float xi2)
{
    const float y = xi1;

    const float phi =
        2.0f * Pi * xi2;

    const float radius =
        std::sqrt(
            std::max(
                0.0f,
                1.0f - y * y));

    return
    {
        radius * std::cos(phi),
        y,
        radius * std::sin(phi)
    };
}

