Color TracePath(
    Ray ray,
    RNG& rng)
{
    Color L = Color::Black();

    // Throughput from camera to current vertex.
    Color beta = Color::White();

    bool previousWasDelta = true;

    for (uint32_t bounce = 0;
         bounce < MaxDepth;
         ++bounce)
    {
        const auto hit =
            scene.Intersect(ray);

        if (!hit)
        {
            // Environment radiance reaching this path.
            L += beta *
                 scene.Environment(
                     ray.Direction);
            break;
        }

        const Material& material =
            scene.Material(
                hit->MaterialID);

        // Surface emission.
        L += beta *
             material.Emission;

        // Direct-light next-event estimation would happen here.

        BSDFSample s =
            SampleBSDF(
                material,
                *hit,
                -ray.Direction,
                rng);

        if (!s.Valid ||
            s.Pdf <= 0.0f)
        {
            break;
        }

        const float cosine =
            std::abs(
                Dot(
                    hit->ShadingNormal,
                    s.Wi));

        beta *=
            s.F *
            (cosine / s.Pdf);

        ray =
            SpawnRay(
                *hit,
                s.Wi);

        // Russian roulette after a few bounces...
    }

    return L;
}

