Color TracePath(
    const Scene& scene,
    Ray ray,
    Sampler& sampler)
{
    Color L =
        Color::Black();

    Color beta =
        Color::White();

    MediumStack media =
        MediumStack::Air();

    // Data needed to MIS-weight a light/environment
    // reached by the previous BSDF sample.
    float previousBSDFPdf = 0.0f;
    bool previousWasDelta = true;

    for (uint32_t bounce = 0;
         bounce < MaxDepth;
         ++bounce)
    {
        //-----------------------------------------------------
        // 1. Closest visibility query.
        //-----------------------------------------------------
        const auto hit =
            scene.IntersectClosest(ray);

        //-----------------------------------------------------
        // 2. Environment miss.
        //-----------------------------------------------------
        if (!hit)
        {
            const Color Le =
                scene.EnvironmentRadiance(
                    ray.Direction);

            if (bounce == 0 ||
                previousWasDelta)
            {
                L +=
                    beta * Le;
            }
            else
            {
                const float lightPdf =
                    scene.EnvironmentPdf(
                        ray.Direction);

                const float weight =
                    PowerHeuristic(
                        previousBSDFPdf,
                        lightPdf);

                L +=
                    beta *
                    Le *
                    weight;
            }

            break;
        }

        const Material& material =
            scene.Material(
                hit->MaterialIndex);

        const Vec3 wo =
            -ray.Direction;

        //-----------------------------------------------------
        // 3. Surface emission.
        //-----------------------------------------------------
        if (material.IsEmitter())
        {
            const Color Le =
                material.Emission;

            if (bounce == 0 ||
                previousWasDelta)
            {
                L +=
                    beta * Le;
            }
            else
            {
                const float lightPdf =
                    scene.PdfLightHit(
                        ray,
                        *hit);

                const float weight =
                    PowerHeuristic(
                        previousBSDFPdf,
                        lightPdf);

                L +=
                    beta *
                    Le *
                    weight;
            }
        }

        //-----------------------------------------------------
        // 4. Explicit direct-light sample.
        //
        // Skip ordinary NEE for pure delta BSDFs because an
        // arbitrary light direction has zero BSDF support.
        //-----------------------------------------------------
        if (!material.IsPureDelta())
        {
            const LightSample light =
                scene.SampleOneLight(
                    *hit,
                    sampler);

            if (light.Pdf > 0.0f)
            {
                const float cosTheta =
                    std::max(
                        Dot(
                            hit->ShadingNormal,
                            light.Wi),
                        0.0f);

                if (cosTheta > 0.0f)
                {
                    const Ray shadow =
                        SpawnShadowRay(
                            *hit,
                            light.Wi,
                            light.Distance);

                    if (!scene.Occluded(shadow))
                    {
                        const Color f =
                            EvaluateBSDF(
                                material,
                                *hit,
                                wo,
                                light.Wi,
                                media);

                        const float bsdfPdf =
                            PdfBSDF(
                                material,
                                *hit,
                                wo,
                                light.Wi,
                                media);

                        const float misWeight =
                            light.Delta
                            ? 1.0f
                            : PowerHeuristic(
                                light.Pdf,
                                bsdfPdf);

                        L +=
                            beta *
                            f *
                            light.Radiance *
                            (
                                cosTheta *
                                misWeight /
                                light.Pdf
                            );
                    }
                }
            }
        }

        //-----------------------------------------------------
        // 5. Sample the BSDF to continue the path.
        //-----------------------------------------------------
        BSDFSample bs =
            SampleBSDF(
                material,
                *hit,
                wo,
                media,
                sampler);

        if (!bs.IsValid())
            break;

        //-----------------------------------------------------
        // 6. Throughput update.
        //-----------------------------------------------------
        if (bs.IsDelta())
        {
            // Delta BSDF routines normally return an F/PDF
            // convention already designed for the exact event.
            beta *=
                bs.F /
                bs.Pdf;
        }
        else
        {
            const float cosine =
                std::abs(
                    Dot(
                        hit->ShadingNormal,
                        bs.Wi));

            if (cosine <= 0.0f ||
                bs.Pdf <= 0.0f)
            {
                break;
            }

            beta *=
                bs.F *
                (cosine / bs.Pdf);
        }

        if (!IsFinite(beta) ||
            MaxComponent(beta) <= 0.0f)
        {
            break;
        }

        //-----------------------------------------------------
        // 7. Update medium ONLY after transmission.
        //-----------------------------------------------------
        if (HasFlag(
                bs.Event,
                BSDFEvent::Transmission))
        {
            UpdateMediumStack(
                media,
                *hit,
                material);
        }

        previousWasDelta =
            bs.IsDelta();

        previousBSDFPdf =
            bs.Pdf;

        //-----------------------------------------------------
        // 8. Spawn robustly offset next ray.
        //-----------------------------------------------------
        ray =
            SpawnSurfaceRay(
                *hit,
                bs.Wi,
                HasFlag(
                    bs.Event,
                    BSDFEvent::Transmission));

        //-----------------------------------------------------
        // 9. Russian roulette.
        //-----------------------------------------------------
        if (bounce >= 3)
        {
            const float survival =
                std::clamp(
                    MaxComponent(beta),
                    0.05f,
                    0.95f);

            if (sampler.Next1D(
                    SampleDimension::Roulette) >
                survival)
            {
                break;
            }

            beta /=
                survival;
        }
    }

    return L;
}

